// One-shot port tool: extracts the built-in icon catalog from the legacy Electron renderer
// (src/renderer/src/utils/icons.ts) into Godot assets.
//
//   node --experimental-strip-types tools/gen_builtin_icons.mjs
//
// Outputs:
//   assets/builtin_icons/<id>.svg     vector icons (the TS `createSvgIcon` data URLs, decoded)
//   assets/builtin_icons/<id>.png     the four embedded PNG icons (default, folder, question, program-manager)
//   src/platform/builtin_icon_catalog.gd   picker order + display names + legacy aliases
//
// The generated files are checked in; after the Electron sources are removed this script is
// kept only for provenance (the catalog + assets are the source of truth).
//
// Godot's SVG rasterizer (ThorVG, no font backend) ignores <text>, so the three icons that used
// text (terminal, calendar, money) are redrawn with stroked glyph paths that match the original
// font-size/position closely.
import { mkdirSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const icons = await import(join(root, 'src/renderer/src/utils/icons.ts'))

const outDir = join(root, 'assets/builtin_icons')
mkdirSync(outDir, { recursive: true })

const TEXT_REPLACEMENTS = {
  terminal: [
    /<text[^>]*>C:\\&gt;_<\/text>/,
    '<g fill="none" stroke="#0f0" stroke-width="1.5">' +
      '<path d="M11 10.2 H7.2 V15.6 H11"/>' +
      '<path d="M16.4 8.6 L19.6 16.4"/>' +
      '<polyline points="21.2,9.6 25.4,12.6 21.2,15.6"/>' +
      '<path d="M26.4 18.6 H31"/></g>' +
      '<rect x="13" y="10.6" width="1.6" height="1.6" fill="#0f0"/>' +
      '<rect x="13" y="14.2" width="1.6" height="1.6" fill="#0f0"/>'
  ],
  calendar: [
    /<text[^>]*>15<\/text>/,
    '<g fill="none" stroke="#000" stroke-width="1.7">' +
      '<path d="M11.2 17.6 L13.4 16 V22.8"/>' +
      '<path d="M20.8 16.1 H17.6 V19.1 H20.2 V22.7 H17.2"/></g>'
  ],
  money: [
    /<text[^>]*>\$<\/text>/,
    '<g fill="none" stroke="#000" stroke-width="1.8">' +
      '<path d="M19.6 13.6 C19.2 11.6 12.6 11.4 12.6 14.4 C12.6 17.2 19.6 16.2 19.6 18.9 C19.6 21.6 13.2 21.2 12.4 19"/></g>' +
      '<line x1="16" y1="9.6" x2="16" y2="22.4" stroke="#000" stroke-width="1.2"/>'
  ]
}

const PNG_NAMES = {
  default: 'default',
  folder: 'folder',
  question: 'question',
  'program-manager': 'program-manager'
}

function decodeSvg(dataUrl) {
  const prefix = 'data:image/svg+xml,'
  if (!dataUrl.startsWith(prefix)) throw new Error('not an svg data url')
  return decodeURIComponent(dataUrl.slice(prefix.length))
}

function decodePng(dataUrl) {
  const prefix = 'data:image/png;base64,'
  if (!dataUrl.startsWith(prefix)) throw new Error('not a png data url')
  return Buffer.from(dataUrl.slice(prefix.length), 'base64')
}

const catalog = []
for (const entry of icons.BUILTIN_ICONS) {
  if (entry.icon.startsWith('data:image/png')) {
    writeFileSync(join(outDir, `${entry.id}.png`), decodePng(entry.icon))
    catalog.push({ id: entry.id, name: entry.name, file: `${entry.id}.png` })
    continue
  }
  let svg = decodeSvg(entry.icon)
  const repl = TEXT_REPLACEMENTS[entry.id]
  if (repl) {
    if (!repl[0].test(svg)) throw new Error(`text pattern for ${entry.id} not found`)
    svg = svg.replace(repl[0], repl[1])
  }
  if (svg.includes('<text')) throw new Error(`${entry.id} still has <text>`)
  writeFileSync(join(outDir, `${entry.id}.svg`), svg + '\n')
  catalog.push({ id: entry.id, name: entry.name, file: `${entry.id}.svg` })
}

// Non-picker PNGs that only legacy names / dialogs refer to.
writeFileSync(join(outDir, 'question.png'), decodePng(icons.QUESTION_ICON))
writeFileSync(join(outDir, 'program-manager.png'), decodePng(icons.APP_ICON))

const lines = []
lines.push('class_name BuiltinIconCatalog')
lines.push('extends RefCounted')
lines.push('## GENERATED by tools/gen_builtin_icons.mjs - do not edit by hand.')
lines.push('## Picker order (port of BUILTIN_ICONS in utils/icons.ts): [id, display name, file].')
lines.push('')
lines.push('const ENTRIES := [')
for (const c of catalog) lines.push(`\t["${c.id}", "${c.name}", "${c.file}"],`)
lines.push(']')
lines.push('')
lines.push('## Legacy icon names kept for data files written by older builds.')
lines.push('const LEGACY := {')
lines.push('\t"default-item.png": "default",')
lines.push('\t"folder.png": "folder",')
lines.push('\t"question.png": "question",')
lines.push('\t"program-manager.png": "program-manager",')
lines.push('}')
lines.push('')
lines.push('## Files for ids that are not in the picker (dialog / app icons).')
lines.push('const EXTRA_FILES := {')
lines.push('\t"question": "question.png",')
lines.push('\t"program-manager": "program-manager.png",')
lines.push('}')
lines.push('')
writeFileSync(join(root, 'src/platform/builtin_icon_catalog.gd'), lines.join('\n'))
console.log(`wrote ${catalog.length} catalog entries`)
